import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("Upload vendor documents", () => {
  test(
    "A file of exactly 10 MiB is accepted",
    { tag: "@DOC-05" },
    async ({ apiAs }) => {
      // Background: signed in as member@northwind.test, and a vendor in status "draft"
      const member = await apiAs("member");
      const unique = uniqueName("DOC-05 Vendor").replace(/\s+/g, "-").toLowerCase();
      const createVendor = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-05 Vendor"),
          category: "software",
          contact_email: `${unique}@example.test`,
        },
      });
      expect(createVendor.status()).toBe(201);
      const vendor = await createVendor.json();
      expect(vendor.status).toBe("draft");

      // When: upload a text file of exactly 10 MiB as kind "contract"
      const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: "contract-10mib.txt",
            mimeType: "text/plain",
            buffer: Buffer.alloc(TEN_MIB, "a"),
          },
        },
      });

      // Then: the response status is 201
      expect(response.status()).toBe(201);
    },
  );
});
